import{_ as r,o as t,c as a,ah as o}from"./chunks/framework.C-FRNfAJ.js";const m=JSON.parse('{"title":"Premiers pas","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/premiers-pas.md","filePath":"src/guide/premiers-pas.md"}'),s={name:"guide/premiers-pas.md"};function n(i,e,u,l,c,p){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="premiers-pas" tabindex="-1">Premiers pas <a class="header-anchor" href="#premiers-pas" aria-label="Permalink to &quot;Premiers pas&quot;">​</a></h1><p>Ce qui vaut pour tous les comptes, quels que soient vos rôles.</p><h2 id="creer-votre-compte" tabindex="-1">Créer votre compte <a class="header-anchor" href="#creer-votre-compte" aria-label="Permalink to &quot;Créer votre compte&quot;">​</a></h2><p>Il n&#39;y a pas de formulaire d&#39;inscription à Kura : le compte naît de votre première démarche, depuis le site NextBoxx, par exemple le dépôt d&#39;une candidature ou l&#39;inscription à un événement. Si votre adresse e-mail a déjà un compte, il est réutilisé.</p><p>Pour un nouveau compte, l&#39;e-mail d&#39;accusé de réception contient un lien pour <strong>choisir votre mot de passe</strong>. Le lien est valable 7 jours et ne sert qu&#39;une fois. S&#39;il a expiré, utilisez « Mot de passe oublié ? » sur la page de connexion.</p><h2 id="vous-connecter" tabindex="-1">Vous connecter <a class="header-anchor" href="#vous-connecter" aria-label="Permalink to &quot;Vous connecter&quot;">​</a></h2><p>Rendez-vous sur la page <strong>Connexion</strong>, saisissez votre e-mail et votre mot de passe. « Se souvenir de moi » garde la session ouverte sur cet appareil.</p><p>Si vous avez ajouté une <strong>clé d&#39;accès</strong>, vous pouvez la préférer : « Se connecter avec une clé d&#39;accès » évite de saisir un mot de passe. Si vous avez activé l&#39;authentification à deux facteurs, Kura vous demande ensuite le code de votre application, ou l&#39;un de vos codes de récupération.</p><p>Un compte inactif pendant un an est désactivé, avec ses données conservées. Il se réactive dès que vous vous reconnectez ou redéposez une candidature.</p><h2 id="securiser-votre-compte" tabindex="-1">Sécuriser votre compte <a class="header-anchor" href="#securiser-votre-compte" aria-label="Permalink to &quot;Sécuriser votre compte&quot;">​</a></h2><p>Dans <strong>Paramètres → Sécurité</strong> :</p><ul><li>changer votre mot de passe ;</li><li>activer l&#39;<strong>authentification à deux facteurs</strong> avec une application d&#39;authentification. Conservez les codes de récupération affichés à l&#39;activation : ils servent si vous perdez votre téléphone ;</li><li>ajouter une ou plusieurs <strong>clés d&#39;accès</strong> (par exemple celle de votre ordinateur ou de votre téléphone), à nommer pour les reconnaître.</li></ul><h2 id="votre-profil" tabindex="-1">Votre profil <a class="header-anchor" href="#votre-profil" aria-label="Permalink to &quot;Votre profil&quot;">​</a></h2><p>Dans <strong>Paramètres → Profil</strong> : votre nom, votre adresse e-mail, votre téléphone et votre photo. Indiquez votre téléphone au format international (par exemple <code>+228 90 00 00 00</code>) : c&#39;est le numéro auquel Kura peut envoyer les rappels de paiement et d&#39;admission sur WhatsApp. Si vous modifiez votre adresse e-mail, un lien de vérification vous est envoyé.</p><p><strong>Paramètres → Langue</strong> choisit le français ou l&#39;anglais, <strong>Paramètres → Apparence</strong> le thème clair, sombre ou celui de votre système.</p><h2 id="demander-un-role" tabindex="-1">Demander un rôle <a class="header-anchor" href="#demander-un-role" aria-label="Permalink to &quot;Demander un rôle&quot;">​</a></h2><p><strong>Paramètres → Rôles</strong> montre vos rôles actifs et l&#39;historique de vos demandes.</p><p>Pour en demander un autre, choisissez-le dans « Demander un rôle », ajoutez un mot de présentation si vous le souhaitez et envoyez. La demande est examinée par la personne responsable de ce rôle ; vous êtes prévenu par e-mail de la décision, motivée en cas de refus. Pendant l&#39;attente, vos autres rôles restent actifs, et un refus ne les modifie pas.</p><p>Les rôles du personnel (Coordinateur, Conseiller, Direction, etc.) ne se demandent pas : l&#39;Administrateur les attribue. Les rôles Candidat, Participant et Apprenant arrivent automatiquement avec la démarche correspondante.</p><h3 id="compte-individu-ou-compte-organisation" tabindex="-1">Compte individu ou compte organisation <a class="header-anchor" href="#compte-individu-ou-compte-organisation" aria-label="Permalink to &quot;Compte individu ou compte organisation&quot;">​</a></h3><p>Un compte est un <strong>individu</strong> ou une <strong>organisation</strong>. Une entreprise qui souhaite financer des apprenants, commander une formation sur devis ou rechercher des profils a besoin d&#39;un compte organisation. Il ne se crée pas à part : on <strong>transforme</strong> son compte individu.</p><p>Dans <strong>Paramètres → Rôles</strong>, rubrique « Compte organisation », saisissez la raison sociale, joignez un justificatif (RCCM ou équivalent, PDF, JPG ou PNG, 5 Mo au plus) et envoyez. L&#39;Administrateur examine la demande. À la validation, le compte prend la raison sociale comme nom, et son historique reste consultable en lecture seule.</p><p>Un compte organisation ne peut plus candidater ni s&#39;inscrire à un événement à titre personnel.</p><h2 id="mes-documents" tabindex="-1">Mes documents <a class="header-anchor" href="#mes-documents" aria-label="Permalink to &quot;Mes documents&quot;">​</a></h2><p><strong>Mes documents</strong> (rubrique Parcours) regroupe tout ce que Kura a produit pour votre compte, chacun avec sa référence et sa date :</p><ul><li>conventions de formation, conventions tripartites de financement et conventions de stage ;</li><li>livret d&#39;accueil ;</li><li>factures et avoirs ;</li><li>certificat, attestation partielle et relevé de notes ;</li><li>lettres de décision de vos candidatures.</li></ul><p>Un filtre par type de document aide à retrouver le bon. Chaque document s&#39;ouvre ou se télécharge en PDF.</p><h2 id="les-notifications" tabindex="-1">Les notifications <a class="header-anchor" href="#les-notifications" aria-label="Permalink to &quot;Les notifications&quot;">​</a></h2><p>Kura vous écrit pour vous prévenir : l&#39;e-mail part toujours. Si votre compte Sève est ouvert, le message arrive aussi dans Sève ; si vous avez renseigné un téléphone, certains rappels (paiements, admission) partent aussi sur WhatsApp. Un canal qui échoue n&#39;empêche pas les autres.</p>',29)])])}const v=r(s,[["render",n]]);export{m as __pageData,v as default};
